/** Cohort marks: public PNGs under /public/logos, with data-URI fallbacks.
 * Mod Tech Labs uses the official stacked mark from modtechlabs.com
 * composited on brand blue (#0333D0) so it reads on the white attendee UI.
 */

export const HOST_LOGOS: Record<string, string> = {
  "August Interactive": "data:image/png;base64,",
  "DBT Aero": "data:image/png;base64,",
  "Field Viewers": "data:image/png;base64,",
  "Makers Equipment": "data:image/png;base64,",
  "Mod Tech Labs": "data:image/png;base64,",
  "nKode": "data:image/png;base64,",
  "NTS Innovations": "data:image/png;base64,",
  "Rook Armor": "data:image/png;base64,",
};

export const SUMMIT_LOCKUP = "data:image/png;base64,";
export const CURTAIN = "data:image/jpeg;base64,";

export const HOST_LOGO_PATHS: Record<string, string> = {
  "August Interactive": "/logos/august-interactive.png",
  "DBT Aero": "/logos/dbt-aero.png",
  "Field Viewers": "/logos/field-viewers.png",
  "Makers Equipment": "/logos/makers-equipment.png",
  "Mod Tech Labs": "/logos/mod-tech-labs.png",
  nKode: "/logos/nkode.png",
  "NTS Innovations": "/logos/nts-innovations.png",
  "Rook Armor": "/logos/rook-armor.png",
};

export function logoFor(name: string): string | null {
  return HOST_LOGO_PATHS[name] ?? HOST_LOGOS[name] ?? null;
}

export function logoPath(name: string): string | null {
  return HOST_LOGO_PATHS[name] ?? null;
}
